def create_dynamic_template(html_template, placeholders_input):
    # Check if all placeholders are present in the input
    placeholders = re.findall(r'\{(\w+)\}', html_template)
    for placeholder in placeholders:
        if placeholder not in placeholders_input:
            raise ValueError(f"Missing placeholder: {placeholder}")

    # Replace placeholders with user inputs
    for placeholder, value in placeholders_input.items():
        html_template = html_template.replace(f"{{{placeholder}}}", html.escape(value))

    return html_template

