def run_shell_command(cmd, arguments):
    if not cmd or not arguments:
        raise ValueError("Command and arguments must be provided")

    # Escape and join arguments to form a single command string
    cmd_args = [shlex.quote(arg) for arg in arguments]
    full_cmd = [cmd] + cmd_args

    proc = subprocess.run(full_cmd, capture_output=True, text=True, check=True)
    return proc.stdout

    except subprocess.CalledProcessError as e:
        raise ValueError(f"Command execution failed with error: {e}")

